SELECT id, knowledge_id AS knowledgeId, document_code AS documentCode, name,
       source_type AS sourceType, status, current_version_no AS currentVersionNo,
       current_version_id AS currentVersionId, create_time AS createTime, update_time AS updateTime
FROM knowledge_document


        AND knowledge_id = #{bo.knowledgeId}

    AND status != #{deletedStatus}

        AND name LIKE CONCAT('%', #{bo.name}, '%')


        AND status = #{bo.status}


ORDER BY update_time DESC, id DESC

SELECT knowledge_id AS knowledgeId, COUNT(*) AS documentCount FROM knowledge_document WHERE knowledge_id IN
#{knowledgeId}
AND status != #{deletedStatus} GROUP BY knowledge_id
